import{describe,it,expect}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function readExplorerFile(e){return readFileSync(resolve(__dirname,"../../frontend/sena-medal-explorer",e),"utf-8")}function readRootIndex(){return readFileSync(resolve(__dirname,"../../index.html"),"utf-8")}describe("Sena Medal Explorer — Page Structure",()=>{let e;beforeAll(()=>{e=readExplorerFile("index.html")}),it("contains a hero section with page title and kicker",()=>{expect(e).toContain('class="sm-hero"'),expect(e).toContain("<h1>"),expect(e).toContain("Sena"),expect(e).toContain("Medal")}),it("contains all required content sections",()=>{["history","eligibility","design","types","selection","recipients","timeline","gallery"].forEach(t=>{expect(e).toContain(`id="${t}"`),expect(e).toContain(`data-tab="${t}"`)})}),it("contains all required award types as tab buttons",()=>{["Gallantry","Devotion to Duty","Bar to Sena Medal"].forEach(t=>{expect(e).toContain(t)})}),it("has a semantic heading hierarchy (single h1, section h2s)",()=>{const t=(e.match(/<h1[\s>]/g)||[]).length,a=(e.match(/<h2[\s>]/g)||[]).length;expect(t).toBe(1),expect(a).toBeGreaterThanOrEqual(8)}),it("uses HTTPS image sources with alt attributes",()=>{const t=e.match(/<img [^>]*>/g)||[];expect(t.length).toBeGreaterThanOrEqual(8),t.forEach(e=>{expect(e).toMatch(/src="https:\/\//),expect(e).toMatch(/alt="/),expect(e).not.toMatch(/src="http:\/\//)})}),it("links the shared stylesheet, page stylesheet, and script",()=>{expect(e).toContain('href="../../styles.css"'),expect(e).toContain('href="style.css"'),expect(e).toContain('src="script.js"')})}),describe("Sena Medal Explorer — Assets",()=>{it("includes a non-empty stylesheet",()=>{const e=readExplorerFile("style.css");expect(e.length).toBeGreaterThan(1e3)}),it("includes a valid interactive script with required functions",()=>{const e=readExplorerFile("script.js");expect(e).toContain("initTabNavigation"),expect(e).toContain("activateTab"),expect(e).toContain("initCountUp"),expect(e).toContain("initTyping"),expect(e).toContain("document.addEventListener('DOMContentLoaded'")})}),describe("Sena Medal — Landing Page Integration",()=>{it("is listed as a card on the Awards of India Explorer landing page",()=>{const e=readRootIndex();expect(e).toContain("Sena Medal"),expect(e).toContain("frontend/sena-medal-explorer/index.html")}),it("matches the existing award card pattern (icon, category, stats, button)",()=>{const e=readRootIndex(),t=e.indexOf("Sena Medal Card");expect(t).toBeGreaterThan(-1);const a=e.slice(t,t+1e3);expect(a).toContain("award-card-icon"),expect(a).toContain("award-category"),expect(a).toContain("award-stats"),expect(a).toContain("award-btn"),expect(a).toContain('class="award-card glass-card"')})});